D=Path(__file__).resolve().parents[1];p=D.parents[2]/'content/ch09/test.md';base=json.loads((D/'technical/baseline.json').read_text())['head'];s=subprocess.check_output(['git','show',base+':content/ch09/test.md'],cwd=D.parents[2],text=True);blocks=list(re.finditer(r'(?ms)^::: quiz\b.*?^:::[ \t]*$',s));assert len(blocks)==16
changes={}
def edit(i,pairs):
 t=blocks[i-1][0]
